const pushData = $input.first().json;

// Пример compareUrl: https://github.com/Andronzi/test-n8n-1/compare/add220efd809...2b8c50eef378
const compareUrl = pushData.compareUrl;

// Извлекаем SHAs из URL
const matches = compareUrl.match(/compare\/(.+?)\.\.\.(.+)$/);
const baseSha = matches ? matches[1] : pushData.commits[0].id + '^'; // fallback
const headSha = matches ? matches[2] : pushData.commits[0].id;

return {
  ...pushData,
  baseSha: baseSha,
  headSha: headSha,
  // Формируем API URL для получения diff
  apiDiffUrl: `https://api.github.com/repos/${pushData.repository}/compare/${baseSha}...${headSha}`
};

const webhookData = $input.first().json.body;
const headers = $input.first().json.headers;

console.log('LOG:HEADERS', headers)

const eventType = headers['x-github-event'];

if (eventType === 'pull_request') {
  const pr = webhookData.pull_request;

  return {
    event: 'pull_request',
    action: webhookData.action, // opened, synchronize, closed
    diffUrl: pr.diff_url, // URL для получения diff
    repository: webhookData.repository.full_name,
    pullRequest: {
      id: pr.number,
      title: pr.title,
      author: pr.user.login,
      url: pr.html_url,
      branch: pr.head.ref,
      baseBranch: pr.base.ref
    },
    raw: webhookData
  };
}

if (eventType === 'push') {
  return {
    event: 'push',
    repository: webhookData.repository.full_name,
    branch: webhookData.ref.replace('refs/heads/', ''),
    commitUrl: webhookData.head_commit.url,
    compareUrl: webhookData.compare,
    commits: webhookData.commits
  };
}

return { 
  event: 'unknown',
  message: 'Unsupported event type',
  eventType 
};

const pushContext = $input.first().json;

// 1. Собираем diff из всех измененных файлов
let fullDiff = '';

if (pushContext.files && pushContext.files.length > 0) {
  for (const file of pushContext.files) {
    if (file.patch) {
      fullDiff += `diff --git a/${file.filename} b/${file.filename}\n`;
      fullDiff += `index ${file.sha.substring(0, 7)}..${file.sha.substring(0, 7)} 100644\n`;
      fullDiff += `--- a/${file.filename}\n`;
      fullDiff += `+++ b/${file.filename}\n`;
      fullDiff += file.patch + '\n\n';
    }
  }
} else {
  fullDiff = 'No changes (binary files or empty commit)';
}

const context = {
  repository: pushContext.repository,
  branch: pushContext.branch,
  eventType: 'push',
  commit: {
    id: pushContext.headSha,
    message: pushContext.commits[0].message,
    author: pushContext.commits[0].author.username,
    url: pushContext.commitUrl,
    stats: {
      total: pushContext.total_commits || 1
    }
  },
  files: pushContext.files ? pushContext.files.map(f => ({
    filename: f.filename,
    status: f.status,
    additions: f.additions,
    deletions: f.deletions,
    changes: f.changes,
    raw_url: f.raw_url
  })) : []
};

const mcpMessage = {
  sender: 'n8n-code-reviewer',
  target: 'code-reviewer-agent',
  payload: {
    diff: fullDiff, // Собранный diff из patch
    context: context // Весь важный контекст
  },
  traceId: 'review_' + Date.now() + '_' + Math.random().toString(36).substr(2, 9),
  timestamp: new Date().toISOString()
};

console.log('✅ Diff собран из', pushContext.files?.length || 0, 'файлов');
console.log('📦 Контекст включает:', context.files.length, 'файлов с изменениями');

return mcpMessage;

// Loop over input items and add a new field called 'myNewField' to the JSON of each one
for (const item of $input.all()) {
  item.json.myNewField = 1;
}

return $input.all();

// Настройки: можно поставить свой chat id здесь
const CHAT_ID = $json.chatId || 123456789; // <- Заменить на свой chat_id, или оставить, если он приходит в $json

const data = $input.first().json;

// Безопасное чтение
const findings = data.review?.findings || [];
const summary = data.review?.summary || data.summary || '—';
const confidence = typeof data.review?.confidence !== 'undefined' ? data.review.confidence : data.confidence;
const iterations = data.review?.iterations ?? data.iterations ?? '—';
const durationMs = data.review?.durationMs ?? data.durationMs ?? 0;
const traceId = data.traceId || data.review?.traceId || '—';

// Экранируем для HTML (Parse Mode = HTML)
function escapeHtml(str) {
  if (str === null || typeof str === 'undefined') return '';
  return String(str)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

const maxIssues = 5; // сколько показывать в сообщении
let text = '';
text += `<b>🧪 Code Review Report</b>\n\n`;
text += `<b>📊 Summary:</b> ${escapeHtml(summary)}\n`;
if (typeof confidence === 'number') text += `<b>🎯 Confidence:</b> ${(confidence * 100).toFixed(0)}% \n`;
text += `<b>🔁 Iterations:</b> ${escapeHtml(iterations)}\n`;
text += `<b>⏱ Duration:</b> ${(Number(durationMs) / 1000).toFixed(1)}s\n`;
text += `<b>🆔 Trace:</b> <code>${escapeHtml(traceId)}</code>\n\n`;

text += `<b>📌 Issues (${findings.length}):</b>\n`;

const shown = findings.slice(0, maxIssues);
shown.forEach((issue, i) => {
  const hypo = escapeHtml(issue.hypothesis || '—');
  const file = escapeHtml(issue.file || '—');
  const line = typeof issue.line !== 'undefined' ? escapeHtml(issue.line) : '—';
  const severity = escapeHtml(issue.severity || '—');
  const suggestion = escapeHtml(issue.suggestion || issue.description || '—');
  const ts = escapeHtml(issue.timestamp || '');
  text += `\n<b>${i + 1}. ${hypo}</b>\n`;
  text += `<b>📄 File:</b> <code>${file}</code>  <b>📍 Line:</b> ${line}\n`;
  text += `<b>⚠️ Severity:</b> ${severity}\n`;
  text += `<b>💡 Suggestion:</b> ${suggestion}\n`;
  if (ts) text += `<i>${ts}</i>\n`;
});

if (findings.length > maxIssues) {
  text += `\n…и ещё <b>${findings.length - maxIssues}</b> проблем(ы). Полный отчёт можно прикрепить как файл.\n`;
}

// Защитный механизм: не отдаём слишком длинное сообщение (Telegram max ~4096 chars).
// Если больше — отрежем текст и добавим пометку.
const MAX_TELEGRAM_LENGTH = 3800;
if (text.length > MAX_TELEGRAM_LENGTH) {
  text = text.slice(0, MAX_TELEGRAM_LENGTH - 200) + '\n\n<b>⚠️ Отчёт усечён (слишком длинный). Полный JSON прикреплён в файле.</b>';
}

// Возвращаем в формате, который легко использовать в Telegram node:
// - $json.chatId
// - $json.text
// При желании можно также вернуть fullReport как строку (используется дальше для файла)
return {
  json: {
    chatId: CHAT_ID,
    text,
    fullReport: JSON.stringify(data, null, 2) // если хочешь прикрепить как документ — см. ниже
  }
};
